"""Package 20 independent interactive art scenes and an editorial download catalogue."""
from pathlib import Path
import json,zipfile,shutil
R=Path(__file__).parent;G=R/'art20'
for d in ['standalone','packages','previews']:(G/d).mkdir(exist_ok=True)
def button(text,action,value='',group='',active=False,cls=''):
    return f'<button class="{cls}" data-action="{action}" data-value="{value}"'+(f' data-group="{group}" aria-pressed="{str(active).lower()}"' if group else '')+f'>{text}</button>'
def swatch(col,action,value,group,active=False,label=''):
    return f'<button class="swatch" aria-label="{label or col}" style="--swatch:{col}" data-action="{action}" data-value="{value}" data-group="{group}" aria-pressed="{str(active).lower()}"></button>'
def ranger(action,label,minimum,maximum,value,step='.01'):
    return f'<label class="row"><small>{label}</small><input aria-label="{label}" data-action="{action}" type="range" min="{minimum}" max="{maximum}" step="{step}" value="{value}"></label>'
def head(tag,title,hint='',extra=''):
    return f'<div class="head {extra}"><small>{tag}</small><h1>{title}</h1>'+ (f'<p class="hint">{hint}</p>' if hint else '')+'</div>'
def bottom(content,cls=''):
    return f'<div class="bottom {cls}">{content}</div>'
b=button;s=swatch
items=[]
def add(slug,name,klass,bg,ink,accent,hint,gesture,ui):
    items.append(dict(slug=slug,name=name,klass=klass,bg=bg,ink=ink,accent=accent,hint=hint,gesture=gesture,ui=ui))
