runtime=(G/'runtime.js').read_text();css=(G/'interface.css').read_text()
for e in items:
    source=(G/'src'/f"{e['slug']}.js").read_text()
    if e['slug'].startswith('10-'):source=(R/'research/more-art/916227-frozen/delaunay.js').read_text()+'\n'+source
    e['license']='CC BY-SA 3.0' if e['slug'].startswith('10-') else 'MIT'
    d=G/e['slug'];d.mkdir(exist_ok=True)
    (d/'scene.js').write_text(source)
    colors=f":root{{--bg:{e['bg']};--ink:{e['ink']};--accent:{e['accent']};--glass:color-mix(in srgb,var(--bg) 72%,transparent);--line:color-mix(in srgb,var(--ink) 22%,transparent)}}"
    shell='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>'+e['name']+'</title>'
    body=f'''<body class="{e['klass']}"><canvas aria-label="{e['name']} interactive artwork"></canvas><main class="ui">{e['ui']}<div class="corner">{b('◌','quiet',cls='icon')}</div></main><button class="reveal" data-reveal aria-label="Show interface">◌</button><div id="error" role="alert"></div>'''
    # Give symbol buttons meaningful accessible names.
    body=body.replace('data-action="quiet"','aria-label="Hide interface" data-action="quiet"')
    body=body.replace('>↺</button>', ' aria-label="Reset artwork">↺</button>').replace('>≋</button>', ' aria-label="Send a breeze">≋</button>')
    if e['klass']=='atlas':
        for symbol,label in [('＋','Raise terrain'),('−','Carve terrain'),('≈','Smooth terrain')]:
            body=body.replace('>'+symbol+'</button>',' aria-label="'+label+'">'+symbol+'</button>')
    ext=shell+'<link rel="stylesheet" href="../interface.css"><style>'+colors+'</style></head>'+body+'<script src="scene.js"></script><script src="../runtime.js"></script></body></html>'
    (d/'index.html').write_text(ext)
    license='Interactive artwork: '+e['name']+'\n'+('Adapted Delaunay triangulation from Frozen Brush 2 by Jason Labbe, https://openprocessing.org/@theRussetPotato/916227\nOriginal library attribution to Jay LaPorte is preserved in the source. Original and adaptation CC BY-SA 3.0: https://creativecommons.org/licenses/by-sa/3.0/\nChanges: stained glass geometry, joint editing, light, touch, offline Canvas implementation.\n' if e['slug'].startswith('10-') else 'Original Canvas implementation created for this collection.\nMIT License\nCopyright (c) 2026 Tao\n\nPermission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:\nThe above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n')
    (d/'LICENSE.txt').write_text(license)
    def safe(t):return t.replace('</script','<\\/script')
    html=shell+'<!-- '+license.replace('--','—')+' --><style>'+css+colors+'</style></head>'+body+'<script>'+safe(source)+'</script><script>'+safe(runtime)+'</script></body></html>'
    (G/'standalone'/f"{e['slug']}.html").write_text(html)
    with zipfile.ZipFile(G/'packages'/f"{e['slug']}.zip",'w',zipfile.ZIP_DEFLATED) as z:
        z.writestr('index.html',html);z.writestr('LICENSE.txt',license);z.writestr('source/scene.js',source);z.writestr('source/runtime.js',runtime);z.writestr('source/interface.css',css)
        z.writestr('UPLOAD.txt','Upload this ZIP with index.html at its root, or use the separate standalone HTML. No external fonts, libraries, images, network calls or integrations are required.\n'+e['hint'])
        if e['slug'].startswith('10-'):z.write(R/'research/more-art/916227-frozen/delaunay.js','original/delaunay.js')

manifest=[{k:v for k,v in e.items() if k!='ui'} for e in items]
(G/'manifest.json').write_text(json.dumps(manifest,indent=2))
cards=''.join(f'''<article data-category="{e['gesture']}"><a class="preview" href="{e['slug']}/"><img src="previews/{e['slug']}.jpg" alt="{e['name']} actual artwork preview"></a><div class="caption"><span>{e['slug'][:2]} / {e['gesture'].split(' · ')[0].upper()}</span><h2>{e['name']}</h2><p>{e['hint']}</p><nav><a href="{e['slug']}/">Enter ↗</a><a href="standalone/{e['slug']}.html" download>HTML ↓</a><a href="packages/{e['slug']}.zip" download>ZIP ↓</a></nav></div></article>''' for e in items)
gallery_css='''*{box-sizing:border-box}body{margin:0;background:#eeece6;color:#323c3b;font-family:Arial,sans-serif}header{max-width:1400px;margin:auto;padding:50px 34px 35px;display:flex;gap:40px;align-items:end;justify-content:space-between}.kicker{font-size:10px;letter-spacing:3px}h1{font:clamp(45px,7vw,94px) Georgia,serif;line-height:1;margin:18px 0 0;letter-spacing:-3px}.intro{max-width:335px;font-size:13px;line-height:1.8;color:#7a7e76}.count{font:56px Georgia;display:block;color:#7f8c7c;margin-bottom:15px}.bar{max-width:1332px;margin:0 auto 28px;padding:16px 0;border-block:1px solid #b5b8ac66;display:flex;gap:20px;font-size:10px;letter-spacing:1.5px;color:#7b8174}.grid{max-width:1400px;margin:auto;padding:0 34px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px}article{background:#f8f6f0;overflow:hidden;border:1px solid #c2c3b522;border-radius:4px}.preview{display:block;height:325px;background:#d9d8ce;overflow:hidden}.preview img{width:100%;height:100%;object-fit:cover;object-position:center 43%}.caption{padding:21px}.caption span{font-size:9px;letter-spacing:1.6px;color:#8b8d7e}h2{font:24px Georgia;margin:10px 0 13px}.caption p{font-size:11px;line-height:1.8;color:#7a7d72;min-height:58px}nav{display:flex;gap:13px;flex-wrap:wrap}a{color:inherit;text-decoration:none}nav a{font-size:10px;border-bottom:1px solid #a4ad9b;padding:5px 0}nav a:first-child{color:#506b55}footer{max-width:1400px;margin:auto;padding:45px 34px;font-size:11px;line-height:1.8;color:#888b80}footer a{text-decoration:underline}button{font:11px Arial;border:1px solid #bac0b0;background:#e0e6d9;color:#4e624d;padding:11px 16px;cursor:pointer;border-radius:2px}.links{display:flex;gap:10px;margin-top:20px}.links a{padding:11px 16px;background:#dce4d5;font-size:11px}.list{margin:25px 34px;max-width:1332px;font-size:11px;line-height:2}details{max-width:1332px;margin:25px auto;padding:18px;border:1px solid #c2c3b588}summary{cursor:pointer;font-size:12px}.downloads{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding-top:20px}.downloads a{font-size:11px;color:#536d52}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:820px){.grid{grid-template-columns:repeat(2,1fr)}header{display:block}.intro{margin-top:25px}.count{display:none}.bar{margin-inline:25px}.downloads{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){header{padding:32px 20px}.grid{padding:0 18px;gap:18px;grid-template-columns:1fr}.preview{height:440px}.caption p{min-height:0}h1{letter-spacing:-2px}.bar{font-size:8px;gap:12px}details{margin:20px 18px}.downloads{grid-template-columns:1fr}}'''
links=''.join(f'<a href="packages/{e["slug"]}.zip" download>{e["slug"][:2]} · {e["name"]} / ZIP ↓</a>' for e in items)
(G/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Twenty Ways to Touch</title><style>'+gallery_css+'</style></head><body><header><div><span class="kicker">COLLECTION THREE / INTERACTIVE ART</span><h1>Twenty ways<br>to touch.</h1></div><div class="intro"><span class="count">20</span>Living things, quiet objects and small worlds.<br>Twenty independent artworks. Different gestures, different materials, different interfaces.<div class="links"><a href="twenty-touch-artworks.zip" download>Download all ZIPs ↓</a><a href="#downloads">Individual files ↘</a></div></div></header><div class="bar"><span>TOUCH & MOUSE</span><span>ENGLISH</span><span>OFFLINE HTML</span><span>ONE ZIP PER ARTWORK</span></div><main class="grid">'+cards+'</main><details id="downloads"><summary>20 individual ZIP downloads</summary><div class="downloads">'+links+'</div></details><footer>Every artwork is independent. Download a single HTML or its ZIP with index.html at the root.<br><a href="../upload-art/">Collection one</a> &nbsp; / &nbsp; <a href="../upload-art-2/">Collection two</a></footer></body></html>')
with zipfile.ZipFile(G/'twenty-touch-artworks.zip','w',zipfile.ZIP_DEFLATED) as z:
    for e in items:z.write(G/'packages'/f"{e['slug']}.zip",f"{e['slug']}.zip")
    z.writestr('READ-ME.txt','20 separate upload packages. Choose one ZIP for each upload. Every individual ZIP contains index.html at its root. Standalone HTML files are also available on the preview page.\n')
(G/'release-notes.txt').write_text('Twenty Ways to Touch\n\n20 independent interactive artworks with distinct content, gestures and interfaces.\n\nEach artwork has an offline single HTML and an individual ZIP with index.html at the root. No external runtime assets or platform integration are required. English interfaces. The complete download contains all 20 individual ZIPs.\n\n'+ '\n'.join(e['name']+' — '+e['gesture'] for e in items))
print('Built 20 offline HTML files, 20 individual upload ZIPs, and one complete download.')
